module largest_connected_component(\n    input clk,\n    input rst_n,\n    input start,\n    
    input [7:0] h_00,\n    input [7:0] h_01,\n    input [7:0] h_02,\n    input [7:0] h_03,\n    input [7:0] h_10,\n    input [7:0] h_11,\n    input [7:0] h_12,\n    input [7:0] h_13,\n    input [7:0] h_20,\n    input [7:0] h_21,\n    input [7:0] h_22,\n    input [7:0] h_23,\n    input [7:0] h_30,\n    input [7:0] h_31,\n    input [7:0] h_32,\n    input [7:0] h_33,\n    
    input [7:0] v_00,\n    input [7:0] v_01,\n    input [7:0] v_02,\n    input [7:0] v_03,\n    input [7:0] v_10,\n    input [7:0] v_11,\n    input [7:0] v_12,\n    input [7:0] v_13,\n    input [7:0] v_20\n  ,input [7:0] v_21,\n    input [7:0] v_22,\n    input [7:0] v_23,\n    input [7:0] v_30,\n    input [7:0] v_31,\n    input [7:0] v_32,\n    input [7:0] v_33,\n    
    output reg [7:0] max_size,\n    output reg done\n);\n\n    // States\n    localparam [3:0] IDLE                   = 4'd0;\n    localparam [3:0] COMPUTE_SUM            = 4'd1;\n    localparam [3:0] INIT_LOOP              = 4'd2;\n    localparam [3:0] CHECK_CELL             = 4'd3;\n    localparam [3:0] INIT_FLOOD_FILL        = 4'd4;\n    localparam [3:0] POP_STACK              = 4'd5;\n    localparam [3:0] PROCESS_NEIGHBOR_UP    = 4'd6;\n    localparam [3:0] PROCESS_NEIGHBOR_DOWN  = 4'd7;\n    localparam [3:0] PROCESS_NEIGHBOR_LEFT  = 4'd8;\n    localparam [3:0] PROCESS_NEIGHBOR_RIGHT = 4'd9;\n    localparam [3:0] UPDATE_MAX             = 4'd10;\n    localparam [3:0] INCREMENT_CELL         = 4'd11;\n    localparam [3:0] CHECK_DONE             = 4'd12;\n    localparam [3:0] FINISH                 = 4'd13;\n    \n    // Registers\n    reg [3:0] state;\n    reg [3:0] next_state;\n    \n    // Processing registers\n    reg [2:0] current_i;        // Up to 4 (0-3 + 1)\n    reg [1:0] current_j;\n    reg [1:0] flood_i, flood_j;\n    \n    // Flood fill components\n    reg [7:0] current_size;\n    reg [7:0] max_size_reg;\n    reg [8:0] current_s_value;   // SUM_WIDTH=9\n    \n    // Visited matrix\n    reg visited [0:3][0:3];\n    \n    // Sum matrix\n    reg [8:0] s [0:3][0:3];     // SUM_WIDTH=9\n    \n    // Stack\n    reg [3:0] stack [0:15];     // {i, j}\n    reg [4:0] sp;               // Stack Pointer (0-16)\n    \n    // Neighbor temp vars\n    reg [1:0] neighbor_i;\n    reg [1:0] neighbor_j;\n    \n    // Induction vars\n    integer i, j;\n    \n    // Main FSM\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all registers\n            state <= IDLE;\n            done <= 1'b0;\n            max_size <= 8'd0;\n            max_size_reg <= 8'd0;\n            current_i <= 3'd0;\n            current_j <= 2'd0;\n            current_size <= 8'd0;\n            current_s_value <= 9'd0;\n            sp <= 5'd0;\n            flood_i <= 2'd0;\n            flood_j <= 2'd0;\n            neighbor_i <= 2'd0;\n            neighbor_j <= 2'd0;\n            \n            // Reset visited\n            for (i = 0; i < 4; i = i + 1) begin\n                for (j = 0; j < 4; j = j + 1) begin\n                    visited[i][j] <= 1'b0;\n                end\n            end\n            \n            // Reset stack\n            for (i = 0; i < 16; i = i + 1) begin\n                stack[i] <= 4'd0;\n            end\n        end else begin\n            done <= 1'b0;\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        state <= COMPUTE_SUM;\n                    end\n                end\n                \n                COMPUTE_SUM: begin\n                    // Calculate s for each cell\n                    s[0][0] <= h_00 + v_00;\n                    s[0][1] <= h_01 + v_01;\n                    s[0][2] <= h_02 + v_02;\n                    s[0][3] <= h_03 + v_03;\n                    \n                    s[1][0] <= h_10 + v_10;\n                    s[1][1] <= h_11 + v_11;\n                    s[1][2] <= h_12 + v_12;\n                    s[1][3] <= h_13 + v_13;\n                    \n                    s[2][0] <= h_20 + v_20;\n                    s[2][1] <= h_21 + v_21;\n                    s[2][2] <= h_22 + v_22;\n                    s[2][3] <= h_23 + v_23;\n                    \n                    s[3][0] <= h_30 + v_30;\n                    s[3][1] <= h_31 + v_31;\n                    s[3][2] <= h_32 + v_32;\n                    s[3][3] <= h_33 + v_33;\n                    state <= INIT_LOOP;\n                end\n                \n                INIT_LOOP: begin\n                    current_i <= 3'd0;\n                    current_j <= 2'd0;\n                    state <= CHECK_CELL;\n                end\n                \n                CHECK_CELL: begin\n                    if (visited[current_i][current_j]) begin\n                        state <= INCREMENT_CELL;\n                    end else begin\n                        current_s_value <= s[current_i][current_j];\n                        current_size <= 8'd0;\n                        // Start flood fill by pushing current cell\n                        sp <= 5'd1;\n                        stack[0] <= {current_i[1:0], current_j}; // {i,j}\n                        visited[current_i][current_j] <= 1'b1;\n                        state <= POP_STACK;\n                    end\n                end\n                \n                INIT_FLOOD_FILL: begin\n                    // Handled in CHECK_CELL\n                    state <= INIT_FLOOD_FILL;  // Should not reach\n                end\n                \n                POP_STACK: begin\n                    if (sp == 5'd0) begin\n                        state <= UPDATE_MAX;\n                    end else begin\n                        // Pop from stack\n                        sp <= sp - 5'd1;\n                        {flood_i, flood_j} <= stack[sp - 1];\n                        current_size <= current_size + 8'd1;\n                        state <= PROCESS_NEIGHBOR_UP;\n                    end\n                end\n                \n                PROCESS_NEIGHBOR_UP: begin\n                    neighbor_i <= flood_i - 1;\n                    neighbor_j <= flood_j;\n                    if (flood_i != 0 && !visited[neighbor_i][neighbor_j] && s[neighbor_i][neighbor_j] == current_s_value) begin\n                        stack[sp] <= {neighbor_i, neighbor_j};\n                        sp <= sp + 5'd1;\n                        visited[neighbor_i][neighbor_j] <= 1'b1;\n                    end\n                    state <= PROCESS_NEIGHBOR_DOWN;\n                end\n                \n                PROCESS_NEIGHBOR_DOWN: begin\n                    neighbor_i <= flood_i + 1;\n                    neighbor_j <= flood_j;\n                    if (flood_i != 3 && !visited[neighbor_i][neighbor_j] && s[neighbor_i][neighbor_j] == current_s_value) begin\n                        stack[sp] <= {neighbor_i, neighbor_j};\n                        sp <= sp + 5'd1;\n                        visited[neighbor_i][neighbor_j] <= 1'b1;\n                    end\n                    state <= PROCESS_NEIGHBOR_LEFT;\n                end\n                \n                PROCESS_NEIGHBOR_LEFT: begin\n                    neighbor_i <= flood_i;\n                    neighbor_j <= flood_j - 1;\n                    if (flood_j != 0 && !visited[neighbor_i][neighbor_j] && s[neighbor_i][neighbor_j] == current_s_value) begin\n                        stack[sp] <= {neighbor_i, neighbor_j};\n                        sp <= sp + 5'd1;\n                        visited[neighbor_i][neighbor_j] <= 1'b1;\n                    end\n                    state <= PROCESS_NEIGHBOR_RIGHT;\n                end\n                \n                PROCESS_NEIGHBOR_RIGHT: begin\n                    neighbor_i <= flood_i;\n                    neighbor_j <= flood_j + 1;\n                    if (flood_j != 3 && !visited[neighbor_i][neighbor_j] && s[neighbor_i][neighbor_j] == current_s_value) begin\n                        stack[sp] <= {neighbor_i, neighbor_j};\n                        sp <= sp + 5'd1;\n                        visited[neighbor_i][neighbor_j] <= 1'b1;\n                    end\n                    state <= POP_STACK;\n                end\n                \n                UPDATE_MAX: begin\n                    if (current_size > max_size_reg) begin\n                        max_size_reg <= current_size;\n                    end\n                    state <= INCREMENT_CELL;\n                end\n                \n                INCREMENT_CELL: begin\n                    if (current_j == 2'd3) begin\n                        current_j <= 2'd0;\n                        current_i <= current_i + 3'd1;\n                    end else begin\n                        current_j <= current_j + 2'd1;\n                    end\n                    state <= CHECK_DONE;\n                end\n                \n                CHECK_DONE: begin\n                    if (current_i == 3'd4) begin\n                        state <= FINISH;\n                    end else begin\n                        state <= CHECK_CELL;\n                    end\n                end\n                \n                FINISH: begin\n                    max_size <= max_size_reg;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n    \nendmodule